package org.brightstats.desktop;
import java.util.*;import javafx.scene.Node;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.concurrent.*;import javafx.animation.*;import javafx.util.Duration;
/** UI reports actual task phases and reported work counts; unknown work is never a percentage. */
final class CalculationProgressView {
 enum Phase{IDLE,WORKING,RENDERING,COMPLETED,CANCELLED,FAILED}
 final Label title=new Label("No calculation started"),phaseLabel=new Label("Idle"),count=new Label("No work count available"),elapsed=new Label();final ProgressBar bar=new ProgressBar();final TextArea history=new TextArea();final Button cancel=new Button("Cancel active calculation");final VBox content=new VBox(10,title,phaseLabel,bar,count,elapsed,new Label("Recent calculation events (no data values)"),history,cancel);final List<String> events=new ArrayList<>();Phase phase=Phase.IDLE;long completed=-1,total=-1,started,generation;Task<?> active;Dialog<Void> opened;final Timeline clock=new Timeline(new KeyFrame(Duration.seconds(1),e->tick()));
 CalculationProgressView(){title.setWrapText(true);phaseLabel.setWrapText(true);history.setEditable(false);history.setPrefRowCount(7);history.setWrapText(true);bar.setMaxWidth(Double.MAX_VALUE);content.getProperties().put("brightstats.redraw",(Runnable)this::refresh);content.setStyle("-fx-padding:18;");content.setPrefSize(600,410);cancel.setDisable(true);cancel.setOnAction(e->{if(active!=null)active.cancel(true);});clock.setCycleCount(Animation.INDEFINITE);}
 void begin(Task<?> task,String caption,long expected){if(active!=null)throw new IllegalStateException("A calculation is already active");generation++;active=task;title.setText(caption);phase=Phase.WORKING;completed=-1;total=expected>0?expected:-1;started=System.nanoTime();elapsed.setText("0 seconds elapsed");cancel.setDisable(false);event("Calculation started");refresh();clock.play();task.stateProperty().addListener((o,a,b)->{if(active!=task)return;if(b==Worker.State.CANCELLED)finish(Phase.CANCELLED);else if(b==Worker.State.FAILED)finish(Phase.FAILED);else if(b==Worker.State.SUCCEEDED){phase=Phase.RENDERING;active=null;cancel.setDisable(true);phaseLabel.setText("Calculation finished; preparing result view");event("Engine returned; rendering results");}});}
 void expected(long expected){total=expected>0?expected:-1;refresh();}
 void report(long actual){if(active==null||actual<0)return;completed=actual;refresh();}
 void rendered(){rendered(generation);}
 void rendered(long expectedGeneration){if(generation==expectedGeneration&&phase==Phase.RENDERING)finish(Phase.COMPLETED);}
 void failed(){if(phase==Phase.WORKING||phase==Phase.RENDERING)finish(Phase.FAILED);}
 void finish(Phase result){phase=result;clock.stop();tick();cancel.setDisable(true);active=null;event(switch(result){case COMPLETED->"Result view ready";case CANCELLED->"Cancelled; no completed report saved";case FAILED->"Calculation or result rendering failed";default->result.toString();});refresh();}
 void event(String value){events.add(java.time.LocalTime.now().withNano(0)+"  "+value);while(events.size()>12)events.removeFirst();history.setText(String.join("\n",events));}
 void refresh(){phaseLabel.setText(switch(phase){case IDLE->"Idle";case WORKING->"Computing; numerical success is evaluated in the final report";case RENDERING->"Preparing result view";case COMPLETED->"Completed — review convergence and failed-attempt accounting in the report";case CANCELLED->"Cancelled — partial work was not saved as a completed report";case FAILED->"Failed — no valid completed result is implied";});boolean running=phase==Phase.WORKING||phase==Phase.RENDERING;if(total>0&&completed>=0&&completed<=total){bar.setProgress((double)completed/total);count.setText(completed+" / "+total+" reported work units; attempted work includes failed fits");}else{bar.setProgress(running?-1:0);count.setText(completed>=0?completed+" work units reported by engine; total unavailable":"Work total unavailable for this numerical phase");}bar.setVisible(UiAppearance.effectiveMotion()==org.brightstats.data.UserPreferences.Motion.FULL||bar.getProgress()>=0);}
 void tick(){if(started>0)elapsed.setText(((System.nanoTime()-started)/1_000_000_000L)+" seconds elapsed");}
 void show(Node owner){if(opened!=null&&opened.isShowing()){opened.getDialogPane().getScene().getWindow().requestFocus();return;}Dialog<Void> dialog=new Dialog<>();opened=dialog;dialog.initOwner(owner.getScene().getWindow());dialog.setTitle("Calculation details");dialog.setResizable(true);dialog.getDialogPane().setContent(content);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);dialog.setOnHidden(e->{dialog.getDialogPane().setContent(null);opened=null;});dialog.show();}
}
